# Generated by manage.py generate_test_cases.
from django.test import override_settings

from bloomerp.config.definition import BloomerpConfig
from bloomerp.models.communication.instant_messaging.im_authorization import (
    IMAuthorization,
)
from bloomerp.tests.base import BloomerpModelTestCase, ModelScenario

from .fixtures import IMFixtures


class TestImauthorizationModel(IMFixtures, BloomerpModelTestCase):
    """Prevent plaintext credential storage and ambiguous sending identities."""

    model = IMAuthorization

    def encrypted_authorization(self) -> IMAuthorization:
        """Persist encrypted credentials and verify their server-only round trip."""
        with override_settings(
            BLOOMERP_CONFIG=BloomerpConfig(email_secret_key="im-test-key")
        ):
            authorization = IMAuthorization(connection=self.external)
            authorization.set_credentials({"access_token": "test-token"})
            authorization.save()
            authorization.refresh_from_db()
            self.assertNotIn("test-token", authorization.credentials)
            self.assertEqual(
                authorization.get_credentials(), {"access_token": "test-token"}
            )
            return authorization

    def get_test_scenarios(self) -> list[ModelScenario[IMAuthorization]]:
        """Reject unencrypted credentials and ownerless personal authorizations."""
        return [
            ModelScenario(
                name="Encrypted credential round trip",
                preparation=self.prepare,
                create_operation=self.encrypted_authorization,
            ),
            self.scenario("Shared authorization", "authorization"),
            self.scenario(
                "Reject plaintext credentials",
                "authorization",
                credentials='{"token":"secret"}',
                invalid=True,
            ),
            self.scenario(
                "Personal authorization needs owner",
                "authorization",
                kind="personal",
                invalid=True,
            ),
        ]
